import{_ as i,a0 as e,w as l,s as u,ao as p,I as a,x as t,a1 as s,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"棄 Ubuntu 轉 Manjaro 一週後的使用體驗 | LCTT x X-CMD","titleTemplate":false,"description":"棄 Ubuntu 轉 Manjaro 一週後的使用體驗 | LCTT (202306) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"棄 Ubuntu 轉 Manjaro 一週後的使用體驗 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"棄 Ubuntu 轉 Manjaro 一週後的使用體驗 | LCTT (202306) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202306/20220423 I Ditched Ubuntu for Manjaro- Here-s What I Think After a Week","title":"棄 Ubuntu 轉 Manjaro 一週後的使用體驗","tag":"202306","desc":""},"relativePath":"202306/20220423 I Ditched Ubuntu for Manjaro- Here-s What I Think After a Week.md","filePath":"[post].md"}'),m={name:"202306/20220423 I Ditched Ubuntu for Manjaro- Here-s What I Think After a Week.md"};function d(f,n,x,j,T,g){const r=e("Link");return l(),u("div",null,[n[43]||(n[43]=p('<h1 id="棄-ubuntu-轉-manjaro-一週後的使用體驗" tabindex="-1">棄 Ubuntu 轉 Manjaro 一週後的使用體驗 <a class="header-anchor" href="#棄-ubuntu-轉-manjaro-一週後的使用體驗" aria-label="Permalink to “棄 Ubuntu 轉 Manjaro 一週後的使用體驗”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202306/27/110506aou1bw5i6prwpm6m.jpg" alt=""></p><p>通常，我用的是基於 Ubuntu 的發行版進行工作，如 Pop!_OS、Zorin OS、Linux Mint 或 Ubuntu 本身。</p><p>它們不會干擾我的工作，同時又提供了順滑的軟件更新。更不用説，它們與我使用的英特爾-英偉達系統相容性良好。</p><p>所有的一切（可能是主觀的）都能開箱即用。</p><p>然而，最近我決定在實體機上切換到 Arch Linux（我大部分時間都是在虛擬機上使用它）。</p><p>結果，我最終選擇使用了 <strong>Manjaro Linux</strong>（一款基於 Arch 的發行版）。</p><h3 id="我選擇-manjaro-linux-的原因" tabindex="-1">我選擇 Manjaro Linux 的原因 <a class="header-anchor" href="#我選擇-manjaro-linux-的原因" aria-label="Permalink to “我選擇 Manjaro Linux 的原因”">​</a></h3><p>令我驚訝的是，即使是使用 <strong>Arch Linux 的立付 USB</strong>，我甚至無法解決 “nouveau DRM: core notifier timeout” 錯誤，更別提繼續安裝了。是的，我知道有嚮導式的 Arch Linux 安裝程序，但是不論怎麼樣，連接的顯示器都會閃爍並突出顯示這個錯誤。</p><p>解決這個問題的最好辦法是不使用我的最近剛剛升級的英偉達顯卡。</p><p><em>很遺憾，我更喜歡英偉達的顯卡……</em></p><p>AMD 的 RX 6600 XT 的價格與 RTX 3060 Ti 相當；對於 1440p 來説，購買那款顯卡是沒有意義的。</p><p>因此，在我這個情況下，RTX 3060 Ti 可能是問題所在。</p><p>雖然我找到了一些解決問題的方法，但是我太懶了。我只是想看看能否在不用付出太多努力的情況下體驗一下 Arch Linux。</p><p><strong>所以，我做了以下的事情：</strong></p>',15)),a("p",null,[n[1]||(n[1]=t("下一個最佳選擇就是嘗試任何一個專門簡化了麻煩的 ",-1)),s(r,{href:"https://itsfoss.com/arch-based-linux-distros/"},{default:o(()=>[...n[0]||(n[0]=[t("最佳的基於 Arch 的發行版",-1)])]),_:1}),n[2]||(n[2]=t("，對吧？",-1))]),n[44]||(n[44]=p('<p>這就是 <strong>Manjaro Linux</strong> 登場的地方。</p><p>Manjaro Linux 是一款流行的基於 Arch 的發行版，並且我注意到每次更新時都有各種改進（在虛擬機上使用時）。</p><p>此外，我喜歡 Manjaro 默認主題的強調色，很適合我的桌面體驗。</p><p>所以，我決定試試看……</p><h3 id="manjaro-linux-起步有點困難" tabindex="-1">Manjaro Linux: 起步有點困難 <a class="header-anchor" href="#manjaro-linux-起步有點困難" aria-label="Permalink to “Manjaro Linux: 起步有點困難”">​</a></h3><p><img src="https://news.itsfoss.com/content/images/wordpress/2022/04/manjaro-linux-home.jpg" alt=""></p><p>使用專有的英偉達驅動程序安裝 Manjaro 時我沒有遇到任何問題。然而，最近的一個小版本更新，<strong>Manjaro Linux 21.2.6，</strong> 把我的系統弄亂了。</p>',7)),a("p",null,[n[4]||(n[4]=t("我無法訪問登錄界面和 ",-1)),s(r,{href:"https://itsfoss.com/what-is-tty-in-linux/"},{default:o(()=>[...n[3]||(n[3]=[t("TTY",-1)])]),_:1}),n[5]||(n[5]=t("（我只能看到主板製造商的標誌）",-1))]),n[45]||(n[45]=p('<p>因此，我只能使用最新的 ISO 重新安裝 Manjaro Linux，到目前為止一切都還好（千萬別出問題）。</p><p>在我使用 Manjaro Linux 的過程中，我注意到了一些事情，有好有壞。</p><p>在這裏，我分享一些我的經歷。如果你還沒有嘗試過，這些經驗應該對你幫助很大，可以讓你更多地瞭解它。</p><h4 id="_1、簡單的安裝" tabindex="-1">1、簡單的安裝 <a class="header-anchor" href="#_1、簡單的安裝" aria-label="Permalink to “1、簡單的安裝”">​</a></h4><p>基於 Arch 的發行版的主要亮點是使安裝過程變得簡單。對我來説，完全沒有遇到任何問題。</p><p>在我的第二塊硬盤上安裝 Manjaro Linux 是一件輕而易舉的事情。引導加載程序正確配置，顯示了 Manjaro 主題的啓動菜單，讓我可以選擇 Windows/Manjaro Linux 進行雙啓動。</p><h4 id="_2、manjaro-歡迎頁" tabindex="-1">2、Manjaro 歡迎頁 <a class="header-anchor" href="#_2、manjaro-歡迎頁" aria-label="Permalink to “2、Manjaro 歡迎頁”">​</a></h4><p><img src="https://news.itsfoss.com/content/images/wordpress/2022/04/manjaro-welcome.jpg" alt=""></p><p>當嘗試新東西時，歡迎體驗在用户體驗中佔據了一大部分重要性。在這方面，Manjaro Linux 沒有讓人失望。</p><p>如果你仔細關注歡迎屏幕上提供的信息，你可以獲得所有必要的信息。</p><p>GNOME 佈局管理器能讓你選擇一個合適的佈局，使你更加舒適。</p><p><img src="https://news.itsfoss.com/content/images/wordpress/2022/04/manjaro-desktop-layout.png" alt=""></p><p>然而，當我嘗試在這裏啓用“<strong>窗口平鋪</strong>”功能時，它卻無法正常工作：</p><p><img src="https://news.itsfoss.com/content/images/wordpress/2022/04/manjaro-settings-welcome.png" alt=""></p><h4 id="_3、包管理器快速且功能豐富" tabindex="-1">3、包管理器快速且功能豐富 <a class="header-anchor" href="#_3、包管理器快速且功能豐富" aria-label="Permalink to “3、包管理器快速且功能豐富”">​</a></h4><p><img src="https://news.itsfoss.com/content/images/wordpress/2022/04/pamac-manjaro.png" alt=""></p><p>考慮到 GNOME 是我最喜歡的桌面環境，我在軟件中心（甚至是像 Pop!_Shop 這樣特定於發行版的商店）上有過糟糕的經歷。</p><p>雖然它們可以完成工作，但有時它們對我的期望反應不及預期。</p>',18)),a("p",null,[n[8]||(n[8]=t("在 Manjaro Linux 中，我發現安裝了 ",-1)),s(r,{href:"https://wiki.manjaro.org/index.php/Pamac"},{default:o(()=>[...n[6]||(n[6]=[t("Pamac",-1)])]),_:1}),n[9]||(n[9]=t(" 作為包管理器。這似乎是 ",-1)),s(r,{href:"https://itsfoss.com/install-remove-software-manjaro/"},{default:o(()=>[...n[7]||(n[7]=[t("在 Manjaro Linux 上安裝和卸載軟件的最佳方式之一",-1)])]),_:1}),n[10]||(n[10]=t("。",-1))]),n[46]||(n[46]=p('<p>根據我的經驗，它在安裝和卸載軟件時非常快速。在安裝某些軟件時，你還會收到關於軟件包衝突或是否需要替換/刪除某些軟件包的提示。當你安裝某些東西時，包管理器提供了關於可選/必需依賴項的大量信息。</p><p>總體來説，體驗非常流暢，沒有出現任何麻煩。為了提升體驗，包管理器還可以通過調整 pamac 的偏好設置，快速啓用對 <strong>Flatpaks/Snaps/AUR</strong> 的支持。</p><p><img src="https://news.itsfoss.com/content/images/wordpress/2022/04/manjaro-pamac-enable-flat-snap.png" alt=""></p><p>所以，你不必使用終端或不同的軟件商店。一切都可在一個統一的平台下獲得，這大大節省了時間。</p><h4 id="_4、嘗試-zsh-shell" tabindex="-1">4、嘗試 ZSH Shell <a class="header-anchor" href="#_4、嘗試-zsh-shell" aria-label="Permalink to “4、嘗試 ZSH Shell”">​</a></h4><p><img src="https://news.itsfoss.com/content/images/wordpress/2022/04/manjaro-terminal.png" alt=""></p><p>我習慣於在基於 Ubuntu 的發行版上使用 Bash shell。然而，Manjaro Linux 默認使用 Zsh shell。我相信 Zsh 比 Bash 更好，不過我很快會在另一篇文章中介紹並深入比較。</p><p>換句話説，我可以直接嘗試不同的東西。令我興奮的是，終端提示符和遵循 Manjaro 品牌的Shell（或終端）的主題也採用了 Manjaro 的強調色，非常令人印象深刻！</p><p><img src="https://news.itsfoss.com/content/images/wordpress/2022/04/manjaro-terminal-update.png" alt=""></p>',9)),a("p",null,[n[12]||(n[12]=t("因此，我沒有必要在此處 ",-1)),s(r,{href:"https://itsfoss.com/customize-linux-terminal/"},{default:o(()=>[...n[11]||(n[11]=[t("自定義終端的外觀",-1)])]),_:1}),n[13]||(n[13]=t("。",-1))]),a("p",null,[n[16]||(n[16]=t("要了解更多信息，你可以查看一些關於 ",-1)),s(r,{href:"https://linuxhandbook.com/why-zsh/"},{default:o(()=>[...n[14]||(n[14]=[t("Zsh 是什麼",-1)])]),_:1}),n[17]||(n[17]=t(" 以及 ",-1)),s(r,{href:"https://linuxhandbook.com/install-zsh/"},{default:o(()=>[...n[15]||(n[15]=[t("如何安裝它",-1)])]),_:1}),n[18]||(n[18]=t(" 的信息。",-1))]),n[47]||(n[47]=a("h4",{id:"_5、缺乏官方軟件支持",tabindex:"-1"},[t("5、缺乏官方軟件支持 "),a("a",{class:"header-anchor",href:"#_5、缺乏官方軟件支持","aria-label":"Permalink to “5、缺乏官方軟件支持”"},"​")],-1)),n[48]||(n[48]=a("p",null,[a("img",{src:"https://news.itsfoss.com/content/images/wordpress/2022/04/insync-manjaro.jpg",alt:""})],-1)),n[49]||(n[49]=a("p",null,"我希望這個情況能夠很快改善。但目前來説，許多軟件/工具只提供對 Ubuntu 和 Fedora 的官方支持。",-1)),n[50]||(n[50]=a("p",null,"你可以在各種工具中找到官方的 DEB/RPM 包，但它們都不能直接在 Manjaro Linux 上使用。",-1)),a("p",null,[n[20]||(n[20]=t("你得依賴 Arch Linux 倉庫或 ",-1)),s(r,{href:"https://itsfoss.com/aur-arch-linux/"},{default:o(()=>[...n[19]||(n[19]=[t("AUR",-1)])]),_:1}),n[21]||(n[21]=t(" 中提供的軟件包。",-1))]),a("p",null,[n[23]||(n[23]=t("幸運的是，很有可能在 AUR 或社區或發行版開發者維護的倉庫中找到所需的軟件。就像我能夠在 Manjaro Linux 上運行 ",-1)),s(r,{href:"https://itsfoss.com/recommends/get-insync/"},{default:o(()=>[...n[22]||(n[22]=[t("Insync",-1)])]),_:1}),n[24]||(n[24]=t("，並使用文件管理器的集成擴展。",-1))]),n[51]||(n[51]=a("p",null,"然而，由於缺乏對該平台的官方支持，你可能會錯過一些功能或快速更新。",-1)),a("p",null,[n[27]||(n[27]=t("當然，如果你依賴於 ",-1)),s(r,{href:"https://itsfoss.com/what-is-flatpak/"},{default:o(()=>[...n[25]||(n[25]=[t("Flatpak",-1)])]),_:1}),n[28]||(n[28]=t(" 或 Snap 軟件包，這對你來説應該不是個問題。此外，如果你是 Linux 的新手，你可以參考我們的 ",-1)),s(r,{href:"https://itsfoss.com/flatpak-guide/"},{default:o(()=>[...n[26]||(n[26]=[t("Flatpak 指南",-1)])]),_:1}),n[29]||(n[29]=t(" 獲取更多信息。",-1))]),n[52]||(n[52]=p('<h4 id="_6、缺少分數縮放" tabindex="-1">6、缺少分數縮放 <a class="header-anchor" href="#_6、缺少分數縮放" aria-label="Permalink to “6、缺少分數縮放”">​</a></h4><p>我有一個由 1080p 和 1440p 分辨率組成的雙顯示器。因此，分數縮放很有幫助，但我可以不用它來操作。</p><p>要在 Manjaro 上啓用分數縮放，你需要安裝支持 X11 縮放的 Mutter 和 GNOME 控制中心軟件包。這些軟件包包括：</p><ul><li><code>mutter-x11-scaling</code></li><li><code>gnome-control-center-x11-scaling</code></li></ul><p>這將替換你現有的 Mutter 和 GNOME 控制中心軟件包。因此，你將失去桌面的默認主題/強調色設置。</p><p>你可能需要使用 GNOME “<ruby>調整<rt>Tweaks</rt></ruby>”應用來將一切調整正確。但是，這可能會令人感覺麻煩。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>總體而言，我喜歡在 Manjaro Linux 上的桌面體驗。如果那個更新沒有搞壞我的系統，我認為我會繼續使用 Manjaro Linux 作為我的新日常操作系統。</p><p>你認為 Manjaro Linux 的優點和缺點是什麼？我在我的新體驗中有遺漏了什麼嗎？作為一個有經驗的 Arch Linux 用户，你有任何建議嗎？</p><p>請在下方評論中告訴我你的想法。</p><p><em>（題圖：MJ/2726c4dd-5611-4ace-8c77-0db894ad6a23）</em></p><hr>',12)),a("p",null,[n[31]||(n[31]=t("via: ",-1)),s(r,{href:"https://news.itsfoss.com/manjaro-linux-experience/"},{default:o(()=>[...n[30]||(n[30]=[t("https://news.itsfoss.com/manjaro-linux-experience/",-1)])]),_:1})]),a("p",null,[n[35]||(n[35]=t("作者：",-1)),s(r,{href:"https://news.itsfoss.com/author/ankush/"},{default:o(()=>[...n[32]||(n[32]=[t("Ankush Das",-1)])]),_:1}),n[36]||(n[36]=t(" 選題：",-1)),s(r,{href:"https://github.com/lujun9972"},{default:o(()=>[...n[33]||(n[33]=[t("lujun9972",-1)])]),_:1}),n[37]||(n[37]=t(" 譯者：ChatGPT 校對：",-1)),s(r,{href:"https://github.com/wxy"},{default:o(()=>[...n[34]||(n[34]=[t("wxy",-1)])]),_:1})]),a("p",null,[n[40]||(n[40]=t("本文由 ",-1)),s(r,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[38]||(n[38]=[t("LCTT",-1)])]),_:1}),n[41]||(n[41]=t(" 原創編譯，",-1)),s(r,{href:"https://linux.cn/"},{default:o(()=>[...n[39]||(n[39]=[t("Linux中國",-1)])]),_:1}),n[42]||(n[42]=t(" 榮譽推出",-1))])])}const L=i(m,[["render",d]]);export{b as __pageData,L as default};
